package dev.srpbackport.tools;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import javax.tools.*;import com.sun.source.tree.*;import com.sun.source.util.*;
/** Resolve declared local/field types before rewriting ambiguous methods such as ItemStack.grow versus box growth. */
public final class WorldPositionCalls {
 static final String BOX="AxisAlignedBB";static final class Edit{int a,b;String text;Edit(int a,int b,String t){this.a=a;this.b=b;text=t;}}
 static String simple(String text){if(text==null)return "";int generic=text.indexOf('<');if(generic>=0)text=text.substring(0,generic);return text.substring(text.lastIndexOf('.')+1);}
 static String render(String source,int a,int b,List<Edit> edits){StringBuilder result=new StringBuilder(source.substring(a,b));List<Edit> selected=new ArrayList<Edit>();for(Edit e:edits)if(e.a>=a&&e.b<=b)selected.add(e);selected.sort((x,y)->Integer.compare(y.a,x.a));for(Edit e:selected)result.replace(e.a-a,e.b-a,e.text);return result.toString();}
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]).toAbsolutePath().normalize();boolean apply=args[1].equals("--apply");Map<String,String> rules=new HashMap<String,String>();rules.put("isAirBlock/1","isAirBlock");rules.put("getTileEntity/1","getTileEntity");rules.put("setBlockToAir/1","setBlockToAir");rules.put("setTileEntity/2","setTileEntity");rules.put("removeTileEntity/1","removeTileEntity");rules.put("canSeeSky/1","canSeeSky");rules.put("getLightFromNeighbors/1","getLightFromNeighbors");rules.put("isBlockModifiable/2","isBlockModifiable");rules.put("isRainingAt/1","isRainingAt");rules.put("markBlockRangeForRenderUpdate/2","markBlockRangeForRenderUpdate");rules.put("isBlockLoaded/1","isBlockLoaded");rules.put("isBlockLoaded/2","isBlockLoaded");rules.put("isAreaLoaded/2","isAreaLoaded");rules.put("isAreaLoaded/3","isAreaLoaded");rules.put("getHeight/1","getHeight");rules.put("getTopSolidOrLiquidBlock/1","getTopSolidOrLiquidBlock");rules.put("getBlockDensity/2","getBlockDensity");rules.put("getChunk/1","getChunk");rules.put("getChunk/2","getChunk");rules.put("canSnowAt/2","canSnowAt");rules.put("destroyBlock/2","destroyBlock");rules.put("scheduleUpdate/3","scheduleUpdate");rules.put("getPrecipitationHeight/1","getPrecipitationHeight");rules.put("isOutsideBuildHeight/1","outsideBuildHeight");
  List<File> files=new ArrayList<File>();try(java.util.stream.Stream<Path> paths=Files.walk(root)){paths.filter(p->p.toString().endsWith(".java")&&!p.toString().replace('\\','/').contains("/backport/")).sorted().forEach(p->files.add(p.toFile()));}
  JavaCompiler compiler=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject> diagnostics=new DiagnosticCollector<JavaFileObject>();StandardJavaFileManager manager=compiler.getStandardFileManager(diagnostics,null,StandardCharsets.UTF_8);JavacTask task=(JavacTask)compiler.getTask(null,manager,diagnostics,Arrays.asList("-proc:none","-source","8"),null,manager.getJavaFileObjectsFromFiles(files));List<CompilationUnitTree> units=new ArrayList<CompilationUnitTree>();for(CompilationUnitTree unit:task.parse())units.add(unit);SourcePositions positions=Trees.instance(task).getSourcePositions();
  Map<String,Map<String,String>> allFields=new HashMap<String,Map<String,String>>();Map<String,Map<String,String>> returns=new HashMap<String,Map<String,String>>();
  for(CompilationUnitTree unit:units)new TreeScanner<Void,Void>(){@Override public Void visitClass(ClassTree type,Void p){String name=type.getSimpleName().toString();if(!name.isEmpty()){Map<String,String> fields=new HashMap<String,String>(),methods=new HashMap<String,String>();for(Tree member:type.getMembers()){if(member instanceof VariableTree){VariableTree v=(VariableTree)member;fields.put(v.getName().toString(),simple(v.getType().toString()));}if(member instanceof MethodTree){MethodTree m=(MethodTree)member;if(m.getReturnType()!=null){String key=m.getName()+"/"+m.getParameters().size(),value=simple(m.getReturnType().toString());methods.put(key,methods.containsKey(key)&&!methods.get(key).equals(value)?"":value);}}}allFields.put(name,fields);returns.put(name,methods);}return super.visitClass(type,p);}}.scan(unit,null);
  Map<Path,String> pending=new LinkedHashMap<Path,String>();List<String> audit=new ArrayList<String>();
  for(CompilationUnitTree unit:units){Path path=Paths.get(unit.getSourceFile().toUri());String source=new String(Files.readAllBytes(path),StandardCharsets.UTF_8);List<Edit> edits=new ArrayList<Edit>();
   new TreeScanner<Void,Void>(){
    final Deque<Map<String,String>> scopes=new ArrayDeque<Map<String,String>>();final Deque<Map<String,String>> fields=new ArrayDeque<Map<String,String>>();final Deque<String> classes=new ArrayDeque<String>();
    int a(Tree t){return (int)positions.getStartPosition(unit,t);}int b(Tree t){return (int)positions.getEndPosition(unit,t);}
    String lookup(String name){for(Map<String,String> scope:scopes)if(scope.containsKey(name))return scope.get(name);return allFields.containsKey(name)?name:"";}
    String type(Tree t){if(t==null)return "";switch(t.getKind()){
     case IDENTIFIER:{String n=((IdentifierTree)t).getName().toString();return n.equals("this")&&!classes.isEmpty()?classes.peek():lookup(n);}
     case PARENTHESIZED:return type(((ParenthesizedTree)t).getExpression());
     case TYPE_CAST:return simple(((TypeCastTree)t).getType().toString());
     case NEW_CLASS:return simple(((NewClassTree)t).getIdentifier().toString());
     case ASSIGNMENT:{AssignmentTree assignment=(AssignmentTree)t;String value=type(assignment.getVariable());return value.isEmpty()?type(assignment.getExpression()):value;}
     case ARRAY_ACCESS:{String value=type(((ArrayAccessTree)t).getExpression());return value.endsWith("[]")?value.substring(0,value.length()-2):"";}
     case CONDITIONAL_EXPRESSION:{ConditionalExpressionTree c=(ConditionalExpressionTree)t;String x=type(c.getTrueExpression()),y=type(c.getFalseExpression());return x.equals(y)?x:c.getTrueExpression().getKind()==Tree.Kind.NULL_LITERAL?y:c.getFalseExpression().getKind()==Tree.Kind.NULL_LITERAL?x:"";}
     case MEMBER_SELECT:{MemberSelectTree s=(MemberSelectTree)t;String n=s.getIdentifier().toString();if(n.equals("boundingBox"))return BOX;if(s.getExpression().toString().equals("this"))for(Map<String,String> row:fields)if(row.containsKey(n))return row.get(n);Map<String,String> row=allFields.get(type(s.getExpression()));return row==null?"":row.getOrDefault(n,"");}
     case METHOD_INVOCATION:{MethodInvocationTree m=(MethodInvocationTree)t;if(m.getMethodSelect() instanceof IdentifierTree){String key=((IdentifierTree)m.getMethodSelect()).getName()+"/"+m.getArguments().size();for(String owner:classes){Map<String,String> row=returns.get(owner);if(row!=null&&row.containsKey(key))return row.get(key);}return "";}if(!(m.getMethodSelect() instanceof MemberSelectTree))return "";MemberSelectTree s=(MemberSelectTree)m.getMethodSelect();String n=s.getIdentifier().toString(),signature=n+"/"+m.getArguments().size();if(n.equals("getEntityBoundingBox")&&m.getArguments().isEmpty())return BOX;if(n.equals("getRenderBoundingBox")&&m.getArguments().isEmpty())return BOX;if(n.equals("getCollisionBoundingBox")&&m.getArguments().isEmpty())return BOX;if((n.equals("getBoundingBox")||n.equals("getCollisionBoundingBox"))&&(m.getArguments().size()==2||m.getArguments().size()==3))return BOX;String receiver=type(s.getExpression()),target=rules.get(signature);if(receiver.equals(BOX)&&target!=null&&!target.equals("contains")&&!target.equals("intersects")&&!target.equals("hasNaN")&&!target.equals("center")&&!target.equals("calculateIntercept"))return BOX;Map<String,String> row=returns.get(receiver);return row==null?"":row.getOrDefault(signature,"");}
     default:return "";
    }}
    void replace(Tree tree,String text,String reason){int x=a(tree),y=b(tree);edits.removeIf(e->e.a>=x&&e.b<=y);edits.add(new Edit(x,y,text));audit.add(root.relativize(path)+"\t"+unit.getLineMap().getLineNumber(x)+"\t"+reason);}
    String arguments(List<? extends ExpressionTree> values){List<String> result=new ArrayList<String>();for(Tree value:values)result.add(render(source,a(value),b(value),edits));return String.join(", ",result);}
    @Override public Void visitClass(ClassTree tree,Void p){Map<String,String> row=new HashMap<String,String>();for(Tree member:tree.getMembers())if(member instanceof VariableTree){VariableTree v=(VariableTree)member;row.put(v.getName().toString(),simple(v.getType().toString()));}scopes.push(row);fields.push(row);classes.push(tree.getSimpleName().toString());super.visitClass(tree,p);classes.pop();fields.pop();scopes.pop();return null;}
    @Override public Void visitMethod(MethodTree tree,Void p){scopes.push(new HashMap<String,String>());for(VariableTree v:tree.getParameters())scopes.peek().put(v.getName().toString(),simple(v.getType().toString()));super.visitMethod(tree,p);scopes.pop();return null;}
    @Override public Void visitBlock(BlockTree tree,Void p){scopes.push(new HashMap<String,String>());super.visitBlock(tree,p);scopes.pop();return null;}
    @Override public Void visitForLoop(ForLoopTree tree,Void p){scopes.push(new HashMap<String,String>());super.visitForLoop(tree,p);scopes.pop();return null;}
    @Override public Void visitEnhancedForLoop(EnhancedForLoopTree tree,Void p){scopes.push(new HashMap<String,String>());super.visitEnhancedForLoop(tree,p);scopes.pop();return null;}
    @Override public Void visitVariable(VariableTree tree,Void p){if(!scopes.isEmpty()&&tree.getType()!=null)scopes.peek().put(tree.getName().toString(),simple(tree.getType().toString()));return super.visitVariable(tree,p);}
    @Override public Void visitMethodInvocation(MethodInvocationTree tree,Void p){super.visitMethodInvocation(tree,p);if(!(tree.getMethodSelect() instanceof MemberSelectTree))return null;MemberSelectTree select=(MemberSelectTree)tree.getMethodSelect();String name=select.getIdentifier().toString(),receiver=select.getExpression().toString();int count=tree.getArguments().size();if(receiver.equals("WorldAccess")||receiver.endsWith(".WorldAccess")||receiver.equals("super")||receiver.endsWith(".super"))return null;
     String target=rules.get(name+"/"+count);
     if(name.equals("isSideSolid")&&(count==2||(count==3&&type(tree.getArguments().get(0)).equals("BlockPos"))))target="isSideSolid";
     if(target==null)return null;String recv=render(source,a(select.getExpression()),b(select.getExpression()),edits);int paren=source.indexOf('(',b(select));String argsCode=render(source,paren+1,b(tree)-1,edits);replace(tree,"WorldAccess."+target+"("+recv+(count==0?"":", "+argsCode)+")",name+"/"+count);return null;
    }
   }.scan(unit,null);
   if(edits.isEmpty())continue;boolean imported=false;for(ImportTree i:unit.getImports())if(i.getQualifiedIdentifier().toString().equals("com.dhanantry.scapeandrunparasites.backport.world.WorldAccess"))imported=true;if(!imported){int at=source.indexOf(';',(int)positions.getEndPosition(unit,unit.getPackageName()))+1;edits.add(new Edit(at,at,"\n\nimport com.dhanantry.scapeandrunparasites.backport.world.WorldAccess;"));}pending.put(path,render(source,0,source.length(),edits));
  }
  for(Diagnostic<?> d:diagnostics.getDiagnostics())if(d.getKind()==Diagnostic.Kind.ERROR)throw new IllegalStateException("Parse failed: "+d);manager.close();if(apply)for(Map.Entry<Path,String> row:pending.entrySet())Files.write(row.getKey(),row.getValue().getBytes(StandardCharsets.UTF_8));Files.write(Paths.get(args[2]),audit,StandardCharsets.UTF_8);System.out.println("World-position expressions: "+audit.size()+" in "+pending.size()+" source units");
 }
}
